import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static long N;
    static int K;

    static class MAT {
        int[][] m = new int[31][31];

        MAT() {
            for (int i = 0; i <= 30; i++) {
                for (int j = 0; j <= 30; j++) {
                    m[i][j] = 0;
                }
            }
        }

        MAT multiply(MAT ot) {
            MAT ret = new MAT();
            for (int i = 0; i <= K; i++) {
                for (int j = 0; j <= K; j++) {
                    long sum = 0;
                    for (int k = 0; k <= K; k++) {
                        sum += (long) m[i][k] * ot.m[k][j];
                    }
                    ret.m[i][j] = (int) (sum % MOD);
                }
            }
            return ret;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        N = sc.nextLong();
        K = sc.nextInt();

        // Convert N to base K
        int[] base_k = new int[64];
        int size = 0;
        long tempN = N;
        while (tempN > 0) {
            base_k[size++] = (int) (tempN % K);
            tempN /= K;
        }

        // Initialize matrices A[0][i]
        MAT[][] A = new MAT[65][30];
        MAT[][] P = new MAT[65][30];
        MAT[][] S = new MAT[65][30];

        for (int i = 0; i < 65; i++) {
            for (int j = 0; j < 30; j++) {
                A[i][j] = new MAT();
                P[i][j] = new MAT();
                S[i][j] = new MAT();
            }
        }

        for (int i = 0; i < K; i++) {
            // Initialize A[0][i]
            for (int j = 0; j <= K; j++) {
                A[0][i].m[j][j] = 1;
            }
            for (int j = 0; j <= K; j++) {
                A[0][i].m[i][j] = 1;
            }
        }

        for (int i = 1; i < size; i++) {
            // Build P[i-1][j]
            P[i - 1][0] = A[i - 1][0];
            for (int j = 1; j < K; j++) {
                P[i - 1][j] = P[i - 1][j - 1].multiply(A[i - 1][j]);
            }
            // Build S[i-1][j]
            S[i - 1][K - 1] = A[i - 1][K - 1];
            for (int j = K - 2; j >= 0; j--) {
                S[i - 1][j] = A[i - 1][j].multiply(S[i - 1][j + 1]);
            }
            // Build A[i][j]
            for (int j = 0; j < K; j++) {
                A[i][j] = S[i - 1][j];
                if (j > 0) {
                    A[i][j] = A[i][j].multiply(P[i - 1][j - 1]);
                }
            }
        }

        // Initialize result matrix res
        MAT res = new MAT();
        for (int i = 0; i <= K; i++) {
            res.m[i][i] = 1;
        }

        int x = 0;
        for (int i = size - 1; i >= 0; i--) {
            for (int j = 0; j < base_k[i]; j++) {
                res = res.multiply(A[i][x]);
                x = (x + 1) % K;
            }
        }

        int ans = 0;
        for (int i = 0; i <= K; i++) {
            ans = (ans + res.m[i][K]) % MOD;
        }

        System.out.println(ans);
        sc.close();
    }
}
